#include <cstdint>
#include <vector>
#include <cmath>
#include <cstring>
#include <cstdio>
#include <cstdlib>

// Jonker-Volgenant shortest augmenting path assignment.
// cost is row-major n*n float64. Returns row->col assignment.
static void jv(const double* cost, int n, int* rowsol) {
    const double BIG = 1e18;
    std::vector<double> u(n, 0.0), v(n, 0.0), d(n);
    std::vector<int> colsol(n, -1), pred(n), rowsol_v(n, -1);
    std::vector<char> scanned(n);

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        double minval = BIG; int imin = 0;
        for (int i = 0; i < n; ++i) {
            double val = cost[i * n + j];
            if (val < minval) { minval = val; imin = i; }
        }
        v[j] = minval;
        if (rowsol_v[imin] < 0) { rowsol_v[imin] = j; colsol[j] = imin; }
    }
    // reduction transfer
    for (int i = 0; i < n; ++i) {
        int j1 = rowsol_v[i];
        if (j1 < 0) continue;
        double minv = BIG;
        const double* row = cost + i * n;
        for (int j = 0; j < n; ++j) if (j != j1) {
            double val = row[j] - v[j];
            if (val < minv) minv = val;
        }
        v[j1] -= minv;
    }
    // augmenting row reduction
    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < n; ++i) {
            if (rowsol_v[i] >= 0) continue;
            const double* row = cost + i * n;
            double umin = BIG, usub = BIG; int j1 = -1, j2 = -1;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (j2 >= 0 && i0 >= 0) { j1 = j2; i0 = colsol[j1]; }
            if (i0 >= 0) rowsol_v[i0] = -1;
            rowsol_v[i] = j1;
            colsol[j1] = i;
        }
    }
    // augmentation
    for (int f = 0; f < n; ++f) {
        if (rowsol_v[f] >= 0) continue;
        std::memset(scanned.data(), 0, n);
        const double* frow = cost + f * n;
        for (int j = 0; j < n; ++j) { d[j] = frow[j] - v[j]; pred[j] = f; }
        int jmin = -1; double mind = 0;
        while (true) {
            mind = BIG; jmin = -1;
            for (int j = 0; j < n; ++j) if (!scanned[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            scanned[jmin] = 1;
            int i = colsol[jmin];
            if (i < 0) break;
            double ui = cost[i * n + rowsol_v[i]] - v[rowsol_v[i]];
            const double* irow = cost + i * n;
            for (int j = 0; j < n; ++j) if (!scanned[j]) {
                double h = irow[j] - v[j] - ui + mind;
                if (h < d[j]) { d[j] = h; pred[j] = i; }
            }
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += d[j] - mind;
        int j = jmin;
        while (true) {
            int i = pred[j];
            int jprev = rowsol_v[i];
            rowsol_v[i] = j;
            colsol[j] = i;
            if (i == f) break;
            j = jprev;
        }
    }
    std::memcpy(rowsol, rowsol_v.data(), n * sizeof(int));
}

int main() {
    int n = 600;
    if (getenv("N")) n = atoi(getenv("N"));
    std::vector<double> M(n * n);
    srand(1);
    for (int i = 0; i < n * n; ++i) M[i] = rand() / double(RAND_MAX);
    std::vector<int> rs(n);
    clock_t t0 = clock();
    jv(M.data(), n, rs.data());
    double dt = double(clock() - t0) / CLOCKS_PER_SEC;
    double c = 0; for (int i = 0; i < n; ++i) c += M[i * n + rs[i]];
    printf("n=%d time=%.4f cost=%.4f\n", n, dt, c);
    return 0;
}
