#include <cstdint>
#include <vector>
#include <cstring>
#include <cstdio>
#include <queue>
#include <cmath>
#include <algorithm>

extern "C" {

struct Node { double d; int j; bool operator<(const Node& o) const { return d > o.d; } };

// idxs: n*k int32 candidate columns, csub: n*k float64 costs. Returns 1 if perfect matching found.
int ssp_knn(const int* idxs, const double* csub, int n, int k, int* rowsol) {
    const double BIG = 1e100;
    std::vector<double> pot_row(n, 0.0), pot_col(n, 0.0);
    std::vector<int> match_row(n, -1), match_col(n, -1);
    std::vector<double> dist(n);
    std::vector<int> prev_row(n), seen_stamp(n, 0);
    std::vector<char> scanned(n);
    int stamp = 0;

    for (int aug = 0; aug < n; ++aug) {
        int f = -1;
        for (int i = 0; i < n; ++i) if (match_row[i] < 0) { f = i; break; }
        ++stamp;
        std::priority_queue<Node> pq;
        for (int j = 0; j < n; ++j) { dist[j] = BIG; scanned[j] = 0; }
        double pf = pot_row[f];
        const int* fi = idxs + f * k;
        const double* fc = csub + f * k;
        for (int t = 0; t < k; ++t) {
            int j = fi[t];
            if (j < 0) continue;
            double rc = fc[t] - pf - pot_col[j];
            if (rc < dist[j]) { dist[j] = rc; prev_row[j] = f; pq.push({rc, j}); }
        }
        int sink = -1; double sinkd = 0;
        while (!pq.empty()) {
            Node cur = pq.top(); pq.pop();
            int jmin = cur.j;
            if (scanned[jmin] || cur.d > dist[jmin] + 1e-15) continue;
            scanned[jmin] = 1;
            int i = match_col[jmin];
            if (i < 0) { sink = jmin; sinkd = cur.d; break; }
            double base = cur.d - pot_row[i];
            // matched edge reduced cost is 0, so row i reached at cur.d
            const int* ii = idxs + i * k;
            const double* ic = csub + i * k;
            for (int t = 0; t < k; ++t) {
                int j = ii[t];
                if (j < 0 || scanned[j] || j == match_row[i]) continue;
                double h = base + ic[t] - pot_col[j];
                // reduced cost of forward edge = cost - pot_row[i] - pot_col[j]
                // h = dist[row i] + rc = cur.d + cost - pot_row[i] - pot_col[j]
                if (h < dist[j]) { dist[j] = h; prev_row[j] = i; pq.push({h, j}); }
            }
        }
        if (sink < 0) { std::memcpy(rowsol, match_row.data(), n*sizeof(int)); return 0; }
        // potential update: pot_col[j] += dist[j] - sinkd for scanned; pot_row similarly
        pot_row[f] += -sinkd;
        for (int j = 0; j < n; ++j) if (scanned[j]) {
            pot_col[j] += dist[j] - sinkd;
            int i = match_col[j];
            if (i >= 0) pot_row[i] += dist[j] - sinkd;
        }
        // augment
        int j = sink;
        while (true) {
            int i = prev_row[j];
            int prev = match_row[i];
            match_row[i] = j;
            match_col[j] = i;
            if (i == f) break;
            j = prev;
        }
    }
    std::memcpy(rowsol, match_row.data(), n * sizeof(int));
    return 1;
}
}
