#include <vector>
#include <cstring>
#include <queue>
#include <cstdint>

extern "C" {

struct Node { double d; int v; bool operator<(const Node& o) const { return d > o.d; } };

// Complete bipartite SSP for validation: idxs NULL means complete, pass M as csub with k==n and idxs identity.
// General: for each row, k candidate columns in idxs (n*k), costs in csub (n*k). -1 idx = absent.
int ssp_knn(const int* idxs, const double* csub, int n, int k, int* rowsol) {
    const double BIG = 1e100;
    int N = 2 * n;
    std::vector<double> pot(N, 0.0);
    std::vector<int> match_row(n, -1), match_col(n, -1);
    std::vector<double> dist(N);
    std::vector<int> prev(N);
    std::vector<char> scanned(N);

    for (int aug = 0; aug < n; ++aug) {
        int f = -1;
        for (int i = 0; i < n; ++i) if (match_row[i] < 0) { f = i; break; }
        for (int x = 0; x < N; ++x) { dist[x] = BIG; scanned[x] = 0; prev[x] = -1; }
        dist[f] = 0.0;
        std::priority_queue<Node> pq;
        pq.push({0.0, f});
        int sink = -1;
        while (!pq.empty()) {
            Node cur = pq.top(); pq.pop();
            int u = cur.v;
            if (scanned[u] || cur.d > dist[u] + 1e-15) continue;
            scanned[u] = 1;
            if (u < n) {
                int i = u;
                int mj = match_row[i];
                double pi = pot[i];
                const int* ii = idxs + i * k;
                const double* ic = csub + i * k;
                for (int t = 0; t < k; ++t) {
                    int j = ii[t];
                    if (j < 0 || j == mj) continue;
                    int v = n + j;
                    if (scanned[v]) continue;
                    double h = cur.d + ic[t] - pi - pot[v];
                    if (h < dist[v]) { dist[v] = h; prev[v] = i; pq.push({h, v}); }
                }
            } else {
                int j = u - n;
                int i = match_col[j];
                if (i < 0) { sink = u; break; }
                if (scanned[i]) continue;
                // reverse matched edge, reduced cost = -(cost - pot[i] - pot[u])
                double cc = BIG;
                const int* ii = idxs + i * k;
                const double* ic = csub + i * k;
                for (int t = 0; t < k; ++t) if (ii[t] == j) { cc = ic[t]; break; }
                double h = cur.d - (cc - pot[i] - pot[u]);
                if (h < dist[i]) { dist[i] = h; prev[i] = u; pq.push({h, i}); }
            }
        }
        if (sink < 0) { std::memcpy(rowsol, match_row.data(), n * sizeof(int)); return 0; }
        double delta = dist[sink];
        for (int x = 0; x < N; ++x) if (scanned[x] && dist[x] < BIG * 0.5) pot[x] += dist[x] - delta;
        int v = sink;
        for (int g = 0; g < N && v != f; ++g) {
            int p = prev[v];
            if (v >= n) {
                int j = v - n, i = p;
                int oldj = match_row[i];
                match_row[i] = j;
                match_col[j] = i;
                if (oldj >= 0 && oldj != j && match_col[oldj] == i) match_col[oldj] = -1;
            }
            v = p;
        }
    }
    std::memcpy(rowsol, match_row.data(), n * sizeof(int));
    return 1;
}
}
