def build(M, k):
    n = M.shape[0]
    idx = np.argpartition(M, k-1, axis=1)[:, :k]
    # mutual
    mask = np.zeros((n, n), np.uint8)
    mask[np.arange(n)[:, None], idx] = 1
    idxT = np.argpartition(M, k-1, axis=0)[:k]
    mask[idxT, np.arange(n)[None, :]] = 1
    deg = mask.sum(1).astype(np.int32)
    off = np.zeros(n+1, np.int32); np.cumsum(deg, out=off[1:])
    cols = np.empty(off[-1], np.int32)
    costs = np.empty(off[-1], np.float64)
    cursor = off[:-1].copy()
    ii, jj = np.nonzero(mask)
    for a, b in zip(ii, jj):
        p = cursor[a]; cols[p] = b; costs[p] = M[a, b]; cursor[a] = p+1
