struct Node { double d; int v; bool operator<(const Node& o) const { return d > o.d; } };

static int ssp(const std::vector<std::vector<int>>& adj,
               const std::vector<std::vector<double>>& adjc,
               int n, std::vector<int>& match_row, std::vector<double>& pot) {
    const double BIG = 1e100;
    int N = 2 * n;
    std::vector<int> match_col(n, -1);
    for (int i = 0; i < n; ++i) if (match_row[i] >= 0) match_col[match_row[i]] = i;
    std::vector<double> dist(N);
    std::vector<int> prev(N);
    std::vector<char> scanned(N);
    if ((int)pot.size() != N) pot.assign(N, 0.0);

    for (int aug = 0; aug < n; ++aug) {
        int f = -1;
        for (int i = 0; i < n; ++i) if (match_row[i] < 0) { f = i; break; }
        if (f < 0) break;
        std::fill(dist.begin(), dist.end(), BIG);
        std::fill(scanned.begin(), scanned.end(), 0);
        dist[f] = 0.0;
        std::priority_queue<Node> pq;
        pq.push({0.0, f});
