        while (!pq.empty()) {
            Node cur = pq.top(); pq.pop();
            int u = cur.v;
            if (scanned[u] || cur.d > dist[u] + 1e-12) continue;
            scanned[u] = 1;
            if (u < n) {
                int i = u, mj = match_row[i];
