                    int j = cols[t];
                    if (j == mj) continue;
                    int v = n + j;
                    if (scanned[v]) continue;
                    double h = cur.d + cs[t] - pi - pot[v];
                    if (h < dist[v]) { dist[v] = h; prev[v] = i; pq.push({h, v}); }
                }
            } else {
                int j = u - n;
                int i = match_col[j];
                if (i < 0) { sink = u; break; }
                if (scanned[i]) continue;
                double cc = 0.0;
                const auto& cols = adj[i];
                const auto& cs = adjc[i];
                for (int t = 0; t < (int)cols.size(); ++t) if (cols[t] == j) { cc = cs[t]; break; }
                double h = cur.d - (cc - pot[i] - pot[u]);
                if (h < dist[i]) { dist[i] = h; prev[i] = u; pq.push({h, i}); }
            }
        }
        if (sink < 0) return 0;
        double delta = dist[sink];
        for (int x = 0; x < N; ++x) if (scanned[x] && dist[x] < BIG * 0.5) pot[x] += dist[x] - delta;
        int v = sink;
        for (int g = 0; g < N + 2 && v != f; ++g) {
            int p = prev[v];
            if (v >= n) {
                int j = v - n, i = p, oldj = match_row[i];
                match_row[i] = j; match_col[j] = i;
                if (oldj >= 0 && oldj != j && match_col[oldj] == i) match_col[oldj] = -1;
            }
            v = p;
        }
    }
