}

extern "C" int solve_emd(const double* M, int n, int k, int* rowsol) {
    std::vector<std::vector<int>> adj(n);
    std::vector<std::vector<double>> adjc(n);
    std::vector<int> order(n);
    std::vector<char> present(n * n, 0);

    auto add_edge = [&](int i, int j) {
        if (present[i * n + j]) return;
        present[i * n + j] = 1;
        adj[i].push_back(j);
        adjc[i].push_back(M[i * n + j]);
    };

    // forward kNN
    for (int i = 0; i < n; ++i) {
        std::iota(order.begin(), order.end(), 0);
        std::nth_element(order.begin(), order.begin() + k, order.end(),
                         [&](int a, int b) { return M[i * n + a] < M[i * n + b]; });
        for (int t = 0; t < k; ++t) add_edge(i, order[t]);
    }
    // reverse kNN (column)
    std::vector<double> colvals(n);
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < n; ++i) { order[i] = i; colvals[i] = M[i * n + j]; }
        std::nth_element(order.begin(), order.begin() + k, order.end(),
                         [&](int a, int b) { return colvals[a] < colvals[b]; });
        for (int t = 0; t < k; ++t) add_edge(order[t], j);
    }

    std::vector<int> match_row(n, -1);
    std::vector<double> pot(2 * n, 0.0);
    if (!ssp(adj, adjc, n, match_row, pot)) return 0;

    const double TOL = 1e-9;
    for (int round = 0; round < 8; ++round) {
        int added = 0;
        for (int i = 0; i < n; ++i) {
            const double* row = M + i * n;
            double pi = pot[i];
            for (int j = 0; j < n; ++j) {
                if (present[i * n + j]) continue;
                if (row[j] - pi - pot[n + j] < -TOL) {
                    add_edge(i, j);
                    ++added;
                }
            }
        }
        if (!added) break;
        std::fill(match_row.begin(), match_row.end(), -1);
        std::fill(pot.begin(), pot.end(), 0.0);
        if (!ssp(adj, adjc, n, match_row, pot)) return 0;
    }
    std::memcpy(rowsol, match_row.data(), n * sizeof(int));
    return 1;
}
